<script setup>
import {ref,computed,onMounted,watch} from 'vue';import {encodeFunctionData,isAddress} from 'viem';
import {publicClient as pc,devWallet,devAccounts,injectedWallet,transact,parseEther,formatEther,zeroAddress,zeroHash,keccak256,toHex,decodeEventLog,stringify,chain} from '../sdk/chain.mjs';
const shelf=ref([]),notebook=ref([]),revisionTitle=ref('A step toward the proof'),restoredRevision=ref(null);const profile=ref(null),profileAddress=ref(''),profileDraft=ref({displayName:'',bio:''}),commentSort=ref('top'),replyTo=ref(null);const operators=ref([]);const page=ref('markets'),config=ref(null),list=ref([]),wallet=ref(devWallet(0)),role=ref(0),account=ref(devAccounts[0].address),sessionAddress=ref(''),observedBlock=ref('0'),portfolio=ref(null),allocation=ref(null),gov=ref(null),activity=ref(null),jobs=ref([]),comments=ref([]),busy=ref(''),notice=ref(''),error=ref(''),lastTx=ref(''),search=ref(''),filter=ref('All topics'),selectedId=ref(''),detailTab=ref('overview'),comment=ref('');
const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'—';const amount=x=>Number(formatEther(BigInt(x??0))).toLocaleString('en-US',{maximumFractionDigits:3});const time=x=>new Date(Number(x)*1000).toLocaleString();
const selected=computed(()=>list.value.find(x=>x.id===selectedId.value));const selectedPosition=computed(()=>portfolio.value?.positions.find(x=>x.id===selectedId.value));const pool=computed(()=>selected.value?.pools[0]);
const filtered=computed(()=>list.value.filter(m=>(filter.value==='All topics'||m.metadata.tag===filter.value)&&`${m.metadata.title} ${m.metadata.description}`.toLowerCase().includes(search.value.toLowerCase())));
const totalLiquidity=computed(()=>list.value.reduce((a,m)=>a+m.pools.reduce((v,p)=>v+Number(formatEther(BigInt(p.totalSupply))),0),0));const probability=m=>{const b=m.pools[0]?.balances;if(!b)return 50;return Math.round(Number(b[1])*100/(Number(b[0])+Number(b[1])));};
const form=ref({title:'',description:'',source:'import Init\n\nnamespace Oncm\n\ndef goal : Prop := ∀ a b : Nat, a + b = b + a\ntheorem solution : goal := Nat.add_comm\n\nend Oncm\n',tag:'Foundations',kind:'0',operatorId:'',parameters:'0x',dependency:'',expected:'1',deadline:'',funding:'100',fee:'2'});const palomarResults=ref(null),palomarQuery=ref('');const published=ref([]),importedPackage=ref(null),editingComment=ref(''),editCommentText=ref(''),moderationReason=ref('');const registration=ref(null),trade=ref({side:0,mode:'buy',amount:'10',slippage:'1'}),quote=ref(null),lpAmount=ref('100'),setAmount=ref('10'),proofSource=ref(''),proofCertificate=ref(''),proofOutcome=ref('1'),allocationText=ref(''),newGov=ref({title:'Approve a new verification profile',profileId:'',verifier:'',manifestHash:'',kind:'profile',enabled:false}),importRef=ref('');
watch(()=>form.value.source,()=>{registration.value=null;},{flush:'sync'});
async function api(url,options={}){const r=await fetch(`/api${url}`,{credentials:'include',...options,headers:{...options.body!==undefined&&{'content-type':'application/json'},...(options.headers??{})},body:options.body===undefined?undefined:stringify(options.body)});const v=await r.json();if(!r.ok)throw new Error(v.error??r.statusText);return v;}
async function refresh(){const d=await api('/markets');list.value=d.markets;observedBlock.value=d.observedBlock;portfolio.value=await api(`/portfolio/${account.value}`);allocation.value=await api(`/allocations?account=${account.value}`);gov.value=await api('/governance');operators.value=await api('/operators');if(selected.value)comments.value=await api(`/comments/${selectedId.value}?sort=${commentSort.value}&viewer=${account.value}`);if(sessionAddress.value)try{jobs.value=await api('/jobs');}catch{sessionAddress.value='';}}
async function act(label,fn){busy.value=label;error.value='';notice.value='';try{const result=await fn();if(result?.transactionHash)lastTx.value=result.transactionHash;notice.value=`${label} completed`;await refresh();return result;}catch(e){error.value=e.shortMessage??e.message;console.error(e);}finally{busy.value='';}}
const send=(address,name,fn,args=[])=>transact(wallet.value,address,config.value.abis[name],fn,args);
async function switchRole(){wallet.value=devWallet(Number(role.value));account.value=wallet.value.account.address;sessionAddress.value='';shelf.value=[];notebook.value=[];restoredRevision.value=null;await api('/auth/logout',{method:'POST'});await refresh();}
async function connect(){await act('Connect wallet',async()=>{if(!window.ethereum)throw new Error('No injected wallet found. Use the clearly labelled local test wallet.');await window.ethereum.request({method:'wallet_addEthereumChain',params:[{chainId:'0x7a8b',chainName:chain.name,nativeCurrency:chain.nativeCurrency,rpcUrls:chain.rpcUrls.default.http}]});await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x7a8b'}]});wallet.value=await injectedWallet(window.ethereum);account.value=wallet.value.account.address;sessionAddress.value='';});}
async function signin(){if(sessionAddress.value?.toLowerCase()===account.value.toLowerCase())return;const {message}=await api('/auth/challenge',{method:'POST',body:{address:account.value}});const signature=await wallet.value.signMessage({message});await api('/auth/verify',{method:'POST',body:{message,signature}});sessionAddress.value=account.value;}
function openMarket(m){selectedId.value=m.id;page.value='detail';detailTab.value='overview';proofSource.value=m.metadata.source??m.metadata.goal??'';quote.value=null;api(`/comments/${m.id}?sort=${commentSort.value}&viewer=${account.value}`).then(v=>comments.value=v);}
async function startJob(action,source=form.value.source){await signin();const job=await api('/jobs',{method:'POST',body:{action,source,statementId:action==='prove'?selected.value?.id:undefined,goalHash:action==='prove'?selected.value?.goalHash:undefined,fixtureId:action==='prove'?selected.value?.metadata.fixtureId:importedPackage.value?.id,profileId:action==='prove'?selected.value?.profileId:config.value.profileId,outcome:Number(proofOutcome.value)}});jobs.value.unshift(job);const poll=async()=>{jobs.value=await api('/jobs');const j=jobs.value.find(x=>x.id===job.id);if(['queued','running'].includes(j.status)){setTimeout(poll,1500);return;}if(j.status==='succeeded'){if(action==='register'&&j.input.source===form.value.source)registration.value=j.result;if(action==='prove')proofCertificate.value=j.result.certificate??'';notice.value=`${action} job completed — inspect its result below`;}else error.value=j.diagnostics;};setTimeout(poll,800);return job;}
async function createMarket(){await act('Create statement and market',async()=>{const f=form.value;const reg=registration.value;if(f.kind==='0'&&!reg?.registrationCertificate)throw new Error('Generate a real registration certificate first.');const m=await api('/metadata',{method:'POST',body:{title:f.title,description:f.description,source:f.source,tag:f.tag,goalHash:reg?.goalHash,externalRef:importRef.value||null,files:importedPackage.value?.files??{},fixtureId:importedPackage.value?.id,provenance:importedPackage.value?.provenance}});let r;if(f.kind==='0')r=await send(config.value.registry,'AgoraRegistry','register',[reg.goalHash,reg.profileId??config.value.profileId,m.uri,reg.registrationCertificate]);else if(f.kind==='4')r=await send(config.value.registry,'AgoraRegistry','registerCustom',[f.operatorId,f.dependency,f.parameters,m.uri]);else r=await send(config.value.registry,'AgoraRegistry','registerDerived',[Number(f.kind),f.dependency,Number(f.expected),BigInt(f.kind==='2'?0:Math.floor(new Date(f.deadline).getTime()/1000)),m.uri]);lastTx.value=r.transactionHash;const e=r.logs.map(l=>{try{return decodeEventLog({abi:config.value.abis.AgoraRegistry,data:l.data,topics:l.topics});}catch{return null;}}).find(x=>x?.eventName==='StatementRegistered');selectedId.value=e.args.statementId;await send(config.value.registry,'AgoraRegistry','createPool',[selectedId.value,parseEther(String(Number(f.fee)/100))]);await refresh();page.value='detail';if(Number(f.funding)>0){const p=selected.value.pools[0];await send(config.value.token,'TrueToken','approve',[p.address,parseEther(f.funding)]);r=await send(p.address,'FixedProductMarketMaker','addFunding',[parseEther(f.funding),[]]);}return r;});}
async function getQuote(){if(!pool.value)throw new Error('Create and fund a pool first');const args=[parseEther(trade.value.amount),Number(trade.value.side)];quote.value=await pc.readContract({address:pool.value.address,abi:config.value.abis.FixedProductMarketMaker,functionName:trade.value.mode==='buy'?'calcBuyAmount':'calcSellAmount',args});}
async function executeTrade(){await act(trade.value.mode==='buy'?'Buy position':'Sell position',async()=>{await getQuote();const p=pool.value.address;const input=parseEther(trade.value.amount);const bps=BigInt(Math.round(Number(trade.value.slippage)*100));const deadline=BigInt(Math.floor(Date.now()/1000)+600);if(trade.value.mode==='buy'){await send(config.value.token,'TrueToken','approve',[p,input]);return send(p,'FixedProductMarketMaker','buyWithDeadline',[input,Number(trade.value.side),quote.value*(10000n-bps)/10000n,deadline]);}await send(config.value.ctf,'ConditionalTokens','setApprovalForAll',[p,true]);return send(p,'FixedProductMarketMaker','sellWithDeadline',[input,Number(trade.value.side),(quote.value*(10000n+bps)+9999n)/10000n,deadline]);});}
async function liquidity(remove=false){await act(remove?'Withdraw liquidity':'Provide liquidity',async()=>{if(!pool.value){await send(config.value.registry,'AgoraRegistry','createPool',[selected.value.id,parseEther('.02')]);await refresh();}const p=pool.value.address,n=parseEther(lpAmount.value);if(remove)return send(p,'FixedProductMarketMaker','removeFunding',[n]);await send(config.value.token,'TrueToken','approve',[p,n]);return send(p,'FixedProductMarketMaker','addFunding',[n,[]]);});}
async function completeSet(merge=false){await act(merge?'Merge complete set':'Split complete set',async()=>{const n=parseEther(setAmount.value);if(!merge)await send(config.value.token,'TrueToken','approve',[config.value.ctf,n]);return send(config.value.ctf,'ConditionalTokens',merge?'mergePositions':'splitPosition',[config.value.token,zeroHash,selected.value.conditionId,[1n,2n],n]);});}
async function redeem(){await act('Redeem settled positions',()=>send(config.value.ctf,'ConditionalTokens','redeemPositions',[config.value.token,zeroHash,selected.value.conditionId,[1n,2n]]));}
async function openShelf(){await act('Open research shelf',async()=>{await signin();shelf.value=await api('/shelf');page.value='shelf';});}
async function saveBookmark(id,notes){await act('Save to research shelf',async()=>{await signin();await api(`/shelf/${id}`,{method:'PUT',body:{notes}});shelf.value=await api('/shelf');});}
async function removeBookmark(id){await act('Remove from shelf',async()=>{await api(`/shelf/${id}`,{method:'DELETE'});shelf.value=await api('/shelf');});}
async function loadNotebook(){await act('Open notebook history',async()=>{await signin();notebook.value=await api('/notebook');});}
async function saveRevision(){await act('Save Lean revision',async()=>{await signin();const r=await api('/notebook',{method:'POST',body:{title:revisionTitle.value,source:form.value.source,profileId:config.value.profileId,basedOn:restoredRevision.value}});restoredRevision.value=r.id;notebook.value=await api('/notebook');});}
function restoreRevision(r){form.value.source=r.source;restoredRevision.value=r.id;revisionTitle.value=r.title+' · continued';page.value='workbench';notice.value='Revision restored into the editor; the saved snapshot is unchanged';}
async function openProfile(address){profileAddress.value=address;profile.value=await api(`/profiles/${address}`);profileDraft.value={displayName:profile.value.displayName,bio:profile.value.bio};page.value='profile';}
async function saveProfile(){await act('Save wallet profile',async()=>{await signin();profile.value=await api('/profiles/me',{method:'PUT',body:profileDraft.value});});}
async function voteComment(c,value){await act('Update comment vote',async()=>{await signin();await api(`/comments/${c.id}/vote`,{method:'POST',body:{value:c.myVote===value?0:value}});});}
async function sortComments(){comments.value=await api(`/comments/${selectedId.value}?sort=${commentSort.value}&viewer=${account.value}`);}
async function postComment(){await act('Publish comment',async()=>{await signin();await api(`/comments/${selectedId.value}`,{method:'POST',body:{text:comment.value,parentId:replyTo.value?.id??null}});comment.value='';replyTo.value=null;});}
async function updateComment(c,moderate=false){await act(moderate?'Moderate comment':'Save comment edit',async()=>{await signin();await api(`/comments/${c.id}`,{method:'PATCH',body:moderate?{hidden:!c.hidden,reason:moderationReason.value}:{text:editCommentText.value}});editingComment.value='';});}
async function submitProof(){await act('Submit verified certificate',()=>send(config.value.registry,'AgoraRegistry','submitProof',[selectedId.value,Number(proofOutcome.value),proofCertificate.value]));}
async function proposeAllocation(){await act('Propose allocation',async()=>{const rows=allocationText.value.trim().split('\n').map(l=>{const [a,s]=l.trim().split(/[\s,]+/);if(!isAddress(a))throw new Error('Each line needs an address and percentage');return{a,s:BigInt(Math.round(Number(s)*10000))};}).sort((a,b)=>a.a.toLowerCase().localeCompare(b.a.toLowerCase()));return send(config.value.allocation,'AllocationController','propose',[BigInt(allocation.value.epoch),rows.map(x=>x.a),rows.map(x=>x.s),BigInt(Math.floor(Date.now()/1000)+86400)]);});}
async function prepareOperator(){const code=await pc.getCode({address:config.value.operatorCandidate});newGov.value={title:'Add resolved_after operator version 1',kind:'operator',profileId:keccak256(toHex('AGORA_RESOLVED_AFTER_V1')),verifier:config.value.operatorCandidate,manifestHash:keccak256(code),enabled:true};}
async function createGovernance(){await act('Propose protocol update',async()=>{await signin();return api('/governance',{method:'POST',body:{...newGov.value,profileId:newGov.value.profileId||config.value.profileId}});});}
async function signGovernance(p){await act('Sign council proposal',async()=>{const signature=await wallet.value.signMessage({message:{raw:p.safeHash}});return api(`/governance/${p.id}/signatures`,{method:'POST',body:{signature}});});}
async function scheduleGovernance(p){await act('Schedule Safe decision',async()=>{const signatures='0x'+[...p.signatures].sort((a,b)=>a.address.toLowerCase().localeCompare(b.address.toLowerCase())).map(s=>s.signature.slice(2,-2)+(parseInt(s.signature.slice(-2),16)+4).toString(16).padStart(2,'0')).join('');return send(config.value.safe,'Safe','execTransaction',[config.value.timelock,0n,p.scheduleData,0,0n,0n,0n,zeroAddress,zeroAddress,signatures]);});}
async function executeGovernance(p){await act('Execute timelocked update',()=>send(config.value.timelock,'AgoraTimelock','execute',[p.target,0n,p.data,zeroHash,p.salt]));}
async function loadActivity(){page.value='activity';activity.value=await api('/activity');}
function download(name,value){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([stringify(value)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
async function exportPackage(){download('agora-statement.json',await api(`/package/${selectedId.value}`));}
function applyPackage(raw){importedPackage.value=raw;form.value.title=raw.metadata?.title??raw.title??'Imported Lean statement';form.value.source=raw.source??'';form.value.description=raw.metadata?.description??'';importRef.value=raw.metadata?.externalRef??raw.repositoryUrl??'';registration.value=raw.registrationCertificate?raw:null;page.value='create';}
async function importPackage(event){const f=event.target.files[0];if(f)await act('Import formal package',async()=>applyPackage(JSON.parse(await f.text())));}
async function searchExternal(){await act('Search Palomar registry',async()=>palomarResults.value=await api(`/palomar?q=${encodeURIComponent(palomarQuery.value)}`));}
async function usePalomar(entry){await act('Import Palomar snapshot',async()=>applyPackage(await api('/import/palomar',{method:'POST',body:{id:entry.id,version:entry.version}})));}
async function importRepository(){await act('Import exact repository snapshot',async()=>applyPackage(await api('/import/snapshot',{method:'POST',body:{url:importRef.value}})));}
onMounted(async()=>{try{config.value=await api('/config');published.value=await api('/fixtures');await refresh();allocationText.value=allocation.value.recipients.map((a,i)=>`${a} ${Number(allocation.value.shares[i])/10000}`).join('\n');}catch(e){error.value=e.message;} });
</script>

<template>
<div class="app-shell">
 <aside class="sidebar"><a class="wordmark" @click="page='markets'"><span class="brand-symbol">∴</span> agora<span class="brand-dot">.</span></a><div class="eyebrow sidebar-caption">A MARKET FOR MATHEMATICAL TRUTH</div>
 <nav><button :class="{active:page==='markets'||page==='detail'}" @click="page='markets'"><span>▦</span> Explore statements</button><button :class="{active:page==='create'}" @click="page='create'"><span>＋</span> Create a market</button><button :class="{active:page==='workbench'}" @click="page='workbench'"><span>λ</span> Lean workbench</button><button :class="{active:page==='portfolio'}" @click="page='portfolio'"><span>◈</span> My positions</button><button :class="{active:page==='shelf'}" @click="openShelf"><span>▱</span> Research shelf</button><button :class="{active:page==='profile'}" @click="openProfile(account)"><span>○</span> My profile</button><div class="nav-divider"></div><button :class="{active:page==='governance'}" @click="page='governance'"><span>◎</span> Governance</button><button :class="{active:page==='revenue'}" @click="page='revenue'"><span>↗</span> Protocol revenue</button><button :class="{active:page==='activity'}" @click="loadActivity"><span>≋</span> Chain activity</button></nav>
 <div class="sidebar-note"><div class="tiny-dot"></div> Agora local network<span>CHAIN 31371 · REAL TRANSACTIONS</span><p>Every outcome settles from a verified proof or a deterministic chain record.</p></div>
 </aside>
 <div class="workspace"><header class="topbar"><span class="top-crumb">Research commons <span>/</span> {{page==='detail'?'Statement':page==='markets'?'Explore':page.replace(/^./,x=>x.toUpperCase())}}</span><div class="wallet-area"><span class="network"><i></i> Block {{observedBlock}}</span><select aria-label="Local test wallet" :disabled="!!busy" v-model="role" @change="switchRole"><option v-for="(name,i) in config?.roles" :value="i">Test wallet: {{name}}</option></select><button class="wallet-button" @click="connect">{{short(account)}} <span>↗</span></button></div></header>
 <div class="status-strip" v-if="busy||error||notice" :class="{error:!!error}"><span>{{busy?`◌ ${busy}…`:error||`✓ ${notice}`}}</span><button v-if="lastTx" @click="loadActivity">Inspect transaction {{short(lastTx)}} ↗</button><button v-if="!busy" @click="error='';notice=''">×</button></div>
 <main v-if="config">
 <section v-if="page==='markets'">
  <div class="page-heading"><div><div class="eyebrow">THE OPEN MATHEMATICS EXCHANGE</div><h1>Good questions.<br><em>Provable answers.</em></h1><p class="intro">Discover formal statements, back an idea, or bring a proof.<br>Markets are open to everyone. Mathematics has the final word.</p></div><div class="hero-formula"><span>∀ ε &gt; 0</span><div class="formula-line"></div><strong>uncertainty → proof</strong><small>LEAN VERIFIED · ONCHAIN SETTLEMENT</small></div></div>
  <div class="stats-grid"><div><span>OPEN STATEMENTS</span><strong>{{list.filter(m=>m.outcome===0).length}} <small>questions worth exploring</small></strong></div><div><span>LIQUIDITY PROVIDED</span><strong>{{totalLiquidity.toLocaleString()}} <small>T in pool shares</small></strong></div><div><span>SETTLED ONCHAIN</span><strong>{{list.filter(m=>m.outcome!==0).length}} <small>verified outcomes</small></strong></div></div>
  <div class="section-heading"><h2>Explore the frontier</h2><button class="text-button" @click="page='create'">Create a statement <span>＋</span></button></div><div class="filterbar"><label class="search"><span>⌕</span><input v-model="search" placeholder="Search a theorem, topic, or idea…" aria-label="Search statements"></label><select v-model="filter"><option>All topics</option><option>Number theory</option><option>Foundations</option><option>Algebra</option><option>Analysis</option><option>Derived markets</option></select><span>{{filtered.length}} statements</span></div>
  <div class="market-grid" v-if="filtered.length"><article class="market-card" v-for="(m,i) in filtered" :key="m.id" @click="openMarket(m)"><div class="card-top"><span class="tag">{{m.metadata.tag||'Foundations'}}</span><span class="state" :class="{settled:m.outcome!==0}"><i></i>{{m.outcome===0?'Open':m.outcome===1?'True':'False'}}</span></div><div class="math-symbol">{{m.kind?'t ≤ d':i%3===0?'ℙ → ∞':i%3===1?'a² + b²':'∀ n ∈ ℕ'}}</div><h3>{{m.metadata.title}}</h3><p>{{m.metadata.description}}</p><div class="card-market"><div><strong>{{m.outcome===0?probability(m):m.outcome===1?100:0}}<small>%</small></strong><span>{{m.outcome===0?'market confidence':'final payout'}}</span></div><div class="mini-chart"><i v-for="n in 12" :style="{height:`${12+(n*7+i*11)%35}px`}"></i></div></div><div class="card-footer"><span>{{amount(m.pools[0]?.totalSupply)}} T liquidity</span><b>View market ↗</b></div></article></div>
  <div v-else class="empty-state"><span class="empty-math">∃ P</span><h3>The next question begins with you.</h3><p>No formal market has been registered on this chain yet.<br>Import a published Lean problem or prepare your own statement.</p><button class="primary" @click="page='create'">Create the first market ↗</button></div>
  <div class="research-note"><span>01 / HOW IT WORKS</span><div><h3>A statement is a commitment.</h3><p>The formal goal, proof profile and collateral are fixed onchain. Every T creates a complete YES + NO set. A valid certificate releases the winning collateral.</p></div><button @click="page='workbench'">Open the workbench ↗</button></div>
 </section>

 <section v-else-if="page==='detail'&&selected">
  <button class="text-button back" @click="page='markets'">← All statements</button><div class="detail-heading"><div><span class="tag">{{selected.metadata.tag}}</span><h1>{{selected.metadata.title}}</h1><p>{{selected.metadata.description}}</p></div><div class="confidence"><strong>{{selected.outcome===0?probability(selected):selected.outcome===1?100:0}}%</strong><span>{{selected.outcome===0?'Market confidence':selected.outcome===1?'Resolved TRUE':'Resolved FALSE'}}</span></div></div>
  <div class="meta-row"><button @click="openProfile(selected.creator)">By {{short(selected.creator)}} ↗</button><span>Statement {{short(selected.id)}}</span><span>Pool {{short(pool?.address)}}</span><button @click="exportPackage">↓ Export package</button><button @click="saveBookmark(selected.id)">☆ Save to shelf</button></div>
  <div class="tabs"><button v-for="t in ['overview','trade','liquidity','proof','discussion']" :class="{active:detailTab===t}" @click="detailTab=t">{{t.replace(/^./,x=>x.toUpperCase())}} <small v-if="t==='discussion'">{{comments.length}}</small></button></div>
  <div class="two-col" v-if="detailTab==='overview'"><div class="panel"><div class="panel-heading"><h2>The formal statement</h2><span>Lean</span></div><pre class="lean-code">{{selected.metadata.source??selected.metadata.goal??'Derived onchain predicate'}}</pre><p class="muted">The goal commitment includes the foundation and environment selected by its proof profile. Human descriptions are supplementary.</p><div class="identity-grid"><label>GOAL HASH<code>{{selected.goalHash}}</code></label><label>PROFILE<code>{{selected.profileId}}</code></label><label>CONDITION<code>{{selected.conditionId}}</code></label></div><div v-if="selected.kind"><p>Derived rule {{selected.kind}} · dependency {{short(selected.dependency)}} · deadline {{selected.deadline==='0'?'none':time(selected.deadline)}}</p><button class="primary" @click="act('Resolve derived statement',()=>send(config.registry,'AgoraRegistry','resolveDerived',[selected.id]))">Resolve from chain state</button></div></div><aside class="panel"><h2>Your position</h2><div class="balance-row"><span>YES</span><strong>{{amount(selectedPosition?.yes)}}</strong></div><div class="balance-row"><span>NO</span><strong>{{amount(selectedPosition?.no)}}</strong></div><div class="balance-row"><span>Pool shares</span><strong>{{amount(selectedPosition?.lp[0]?.balance)}}</strong></div><button class="primary full" @click="detailTab='trade'" v-if="selected.outcome===0">Trade this statement ↗</button><button class="primary full" @click="redeem" v-else>Redeem settled positions</button><hr><h3>Complete outcome sets</h3><p class="muted">Lock 1 T to create 1 YES + 1 NO. Merge equal amounts of both sides to recover T.</p><label>AMOUNT T<input v-model="setAmount" type="number" min="0" step="0.1"></label><div class="button-row"><button @click="completeSet(false)">Split T</button><button @click="completeSet(true)">Merge set</button></div></aside></div>
  <div class="two-col" v-if="detailTab==='trade'"><div class="panel trade-panel"><h2>Take a position</h2><p class="muted">Swaps execute directly in the Gnosis fixed product market maker.</p><div class="segmented"><button :class="{active:trade.mode==='buy'}" @click="trade.mode='buy';quote=null">Buy</button><button :class="{active:trade.mode==='sell'}" @click="trade.mode='sell';quote=null">Sell for T</button></div><div class="outcome-selector"><button :class="{active:trade.side===0}" @click="trade.side=0;quote=null">YES <span>{{probability(selected)}}%</span></button><button :class="{active:trade.side===1}" @click="trade.side=1;quote=null">NO <span>{{100-probability(selected)}}%</span></button></div><label>{{trade.mode==='buy'?'T TO SPEND':'T TO RECEIVE'}}<input v-model="trade.amount" type="number" min="0" @input="quote=null"></label><label>SLIPPAGE LIMIT %<input v-model="trade.slippage" type="number" min="0" max="20"></label><div class="quote"><span>{{trade.mode==='buy'?'Estimated outcome received':'Estimated outcome spent'}}</span><strong>{{quote===null?'—':amount(quote)}}</strong></div><div class="button-row"><button @click="act('Calculate quote',getQuote)">Preview</button><button class="primary" :disabled="busy||selected.outcome!==0" @click="executeTrade">{{trade.mode==='buy'?'Buy':'Sell'}} {{trade.side===0?'YES':'NO'}} ↗</button></div><p v-if="selected.outcome!==0" class="notice">This FPMM has settled. Trading and new funding are stopped; withdrawal and redemption remain available.</p></div><div class="panel"><h2>Know the terms</h2><div class="balance-row"><span>Trading fee</span><strong>{{Number(pool?.fee??0)/1e16}}%</strong></div><div class="balance-row"><span>To liquidity providers</span><strong>80% of fee</strong></div><div class="balance-row"><span>Protocol revenue</span><strong>20% of fee</strong></div><p class="muted">The protocol portion is transferred in T to the current immutable epoch during this transaction. Confirmation is required for approvals and the swap.</p></div></div>
  <div class="two-col" v-if="detailTab==='liquidity'"><div class="panel"><h2>Support a liquid market</h2><p class="muted">The FPMM creates the necessary conditional positions from your T. An imbalanced pool can return residual outcome tokens.</p><label>AMOUNT — T TO ADD / LP SHARES TO REMOVE<input v-model="lpAmount" type="number" min="0"></label><div class="button-row"><button class="primary" :disabled="busy||selected.outcome!==0" @click="liquidity(false)">Provide liquidity</button><button :disabled="!!busy" @click="liquidity(true)">Withdraw LP shares</button></div><button class="text-button" v-if="pool" @click="act('Claim LP trading fees',()=>send(pool.address,'FixedProductMarketMaker','withdrawFees',[account]))">Claim accrued LP fees ↗</button></div><div class="panel"><h2>Pool inventory</h2><div class="balance-row"><span>YES reserve</span><strong>{{amount(pool?.balances[0])}}</strong></div><div class="balance-row"><span>NO reserve</span><strong>{{amount(pool?.balances[1])}}</strong></div><div class="balance-row"><span>Your LP shares</span><strong>{{amount(selectedPosition?.lp[0]?.balance)}}</strong></div><p class="muted">Withdrawal returns the current composition of reserves. Receiving all value in T depends on merging, redemption or an available trade.</p></div></div>
  <div v-if="detailTab==='proof'" class="two-col"><div class="panel"><h2>Bring the proof</h2><p class="muted">Lean diagnostics, a zk certificate and an onchain settlement are separate steps.</p><label>PROVE THE OUTCOME<select v-model="proofOutcome"><option value="1">TRUE — prove P</option><option value="2">FALSE — prove ¬P</option></select></label><textarea class="code-input" v-model="proofSource" rows="12"></textarea><div class="button-row"><button @click="act('Check Lean',()=>startJob('check',proofSource))">Check Lean</button><button class="primary" @click="act('Start real proving',()=>startJob('prove',proofSource))">Generate certificate</button></div></div><div class="panel"><h2>Submit the certificate</h2><label>VERIFIABLE CERTIFICATE · HEX<textarea class="code-input" v-model="proofCertificate" rows="7" placeholder="0x…"></textarea></label><button class="primary full" :disabled="busy||!proofCertificate||selected.outcome!==0" @click="submitProof">Verify & settle onchain ↗</button><p class="muted">There is no admin resolution method. Invalid goals, outcomes and certificates are rejected by the contract.</p><div class="job" v-for="j in jobs.filter(j=>j.input.statementId===selected.id)"><b>{{j.input.action}} · {{j.status}}</b><pre>{{j.diagnostics}}</pre><button v-if="j.result" @click="download('agora-proof.json',j.result)">Download result</button></div></div></div>
  <div class="panel discussion" v-if="detailTab==='discussion'"><div class="panel-heading"><h2>Discuss the mathematics</h2><select v-model="commentSort" @change="sortComments" aria-label="Sort comments"><option value="top">Top · highest score</option><option value="new">New · latest first</option></select></div><p class="reply-banner" v-if="replyTo">Replying to {{replyTo.profile?.displayName??short(replyTo.author)}} <button @click="replyTo=null">Cancel reply</button></p><p class="muted">Comments are offchain. Sign in with your wallet to participate; no gas is charged.</p><label v-if="account.toLowerCase()===config.accounts[0].toLowerCase()">MODERATION REASON<input v-model="moderationReason" placeholder="Reason when hiding a comment"></label><textarea v-model="comment" rows="4" placeholder="Share an observation, an approach, or a reference…"></textarea><button class="primary" @click="postComment" :disabled="busy||!comment">Publish comment</button><article v-for="c in comments" :key="c.id" class="comment" :style="{marginLeft:`${Math.min(c.depth??0,6)*18}px`}"><div class="comment-votes"><button :class="{chosen:c.myVote===1}" :disabled="!!busy||c.author.toLowerCase()===account.toLowerCase()" @click="voteComment(c,1)" aria-label="Upvote comment">▲</button><strong>{{c.score??0}}</strong><button :class="{chosen:c.myVote===-1}" :disabled="!!busy||c.author.toLowerCase()===account.toLowerCase()" @click="voteComment(c,-1)" aria-label="Downvote comment">▼</button></div><div class="comment-avatar">{{c.author.slice(2,4).toUpperCase()}}</div><div><button class="profile-link" @click="openProfile(c.author)">{{c.profile?.displayName??short(c.author)}} <code>{{short(c.author)}}</code></button><time>{{new Date(c.createdAt).toLocaleString()}}</time><p>{{c.hidden?`Hidden by moderator: ${c.reason}`:c.text}}</p><small v-if="c.history?.length">Edited · {{c.history.length}} earlier versions retained</small><div class="button-row"><button @click="replyTo=c">Reply</button><button v-if="c.author.toLowerCase()===account.toLowerCase()" @click="editingComment=c.id;editCommentText=c.text">Edit</button><button v-if="account.toLowerCase()===config.accounts[0].toLowerCase()" @click="updateComment(c,true)">{{c.hidden?'Restore':'Hide'}}</button></div><div v-if="editingComment===c.id"><textarea v-model="editCommentText"></textarea><button @click="updateComment(c)">Save edit</button></div><details v-if="c.history?.length"><summary>Edit history</summary><p v-for="h in c.history">{{h.at}} · {{h.text}}</p></details></div></article></div>
 </section>

 <section v-else-if="page==='create'" class="narrow-page"><div class="eyebrow">START WITH A PRECISE QUESTION</div><h1>Create a statement.</h1><p class="intro">Fix the formal goal. Open a market. Let anyone work toward a proof.</p><div class="panel"><h2>01 <span>The question</span></h2><label>TITLE<input v-model="form.title" placeholder="A concise name for your statement"></label><div class="form-grid"><label>TOPIC<select v-model="form.tag"><option>Foundations</option><option>Number theory</option><option>Algebra</option><option>Analysis</option><option>Derived markets</option></select></label><label>STATEMENT TYPE<select v-model="form.kind"><option value="0">Lean mathematical goal</option><option value="1">Resolved by a deadline</option><option value="2">Resolves to an outcome</option><option value="3">Resolves to an outcome by deadline</option><option value="4">Governance-approved operator</option></select></label></div><label>HUMAN DESCRIPTION<textarea v-model="form.description" rows="3" placeholder="What does this question ask, and why does it matter?"></textarea></label><template v-if="form.kind==='0'"><p class="muted">This profile uses <code>Oncm.goal : Prop</code> and <code>Oncm.solution</code>. Goal commitments include the pinned foundation. Changing source requires sealing again.</p><label>LEAN SOURCE<textarea v-model="form.source" rows="8" class="code-input"></textarea></label><div class="button-row"><button @click="act('Prepare registered Lean goal',()=>startJob('register'))">Check & seal the goal</button><span class="good" v-if="registration?.registrationCertificate">✓ Registration certificate ready</span></div><p class="muted" v-if="!config.proofAvailable">The real proof bridge is not installed in this deployment yet. Requests fail explicitly; no test certificate will be substituted.</p></template><template v-else><label>DEPENDENCY<select v-model="form.dependency"><option value="">Choose a registered statement</option><option v-for="m in list" :value="m.id">{{m.metadata.title}}</option></select></label><label v-if="form.kind==='4'">OPERATOR VERSION<select v-model="form.operatorId"><option v-for="o in operators" :value="o.id">{{o.id}}</option></select></label><label v-if="form.kind==='4'">ENCODED OPERATOR PARAMETERS<textarea class="code-input" v-model="form.parameters"></textarea></label><label v-if="form.kind!=='1'&&form.kind!=='4'">EXPECTED OUTCOME<select v-model="form.expected"><option value="1">TRUE</option><option value="2">FALSE</option></select></label><label v-if="form.kind!=='2'&&form.kind!=='4'">DEADLINE · YOUR LOCAL TIME<input v-model="form.deadline" type="datetime-local"></label></template></div><div class="panel"><h2>02 <span>The market</span></h2><div class="form-grid"><label>INITIAL LIQUIDITY · T<input v-model="form.funding" type="number" min="0"></label><label>TRADING FEE %<input v-model="form.fee" type="number" min="0" max="10" step=".1"></label></div><p class="muted">Your T creates complete conditional sets in Gnosis CTF. You receive FPMM liquidity shares. Future protocol fees are paid into immutable allocation epochs.</p><button class="primary full" :disabled="busy||!form.title||(form.kind==='0'&&!registration?.registrationCertificate)" @click="createMarket">Register statement & create market ↗</button></div><div class="panel"><h2>Import an existing formalization</h2><label>SEARCH RECENT PALOMAR ENTRIES<input v-model="palomarQuery" placeholder="Theorem, title, or topic"></label><button @click="searchExternal" :disabled="!!busy">Search live Palomar registry</button><div v-if="palomarResults"><small>{{palomarResults.scope}} · {{palomarResults.entries.length}} matches</small><article class="published-fixture" v-for="e in palomarResults.entries"><h3>{{e.title}}</h3><p>{{e.abstract}}</p><code>{{e.source.commit}}</code><button @click="usePalomar(e)" :disabled="!!busy">Import formalization draft</button></article></div><article class="published-fixture" v-for="f in published"><h3>{{f.title}}</h3><p>{{f.description}}</p><code>{{f.commit}}</code><button class="primary" @click="applyPackage(f)">Use this published Lean task ↗</button></article><p>Use a content-addressed package or an exact published repository snapshot. External registry status is informative; the protocol checks its own certificates.</p><label>REPOSITORY / PALOMAR REFERENCE<input v-model="importRef" placeholder="https://github.com/owner/repository/blob/40-char-commit/Statement.lean"></label><button @click="importRepository" :disabled="!!busy||!importRef">Fetch exact snapshot</button><label class="file-button">Import package JSON<input type="file" accept=".json" @change="importPackage"></label><a class="text-button" href="https://palomar-registry.org/" target="_blank" rel="noreferrer">Explore Palomar ↗</a></div><div class="job" v-for="j in jobs.filter(x=>x.input.action==='register')"><b>Registration · {{j.status}}</b><pre>{{j.diagnostics}}</pre></div></section>

 <section v-else-if="page==='workbench'"><div class="eyebrow">A PLACE TO THINK FORMALLY</div><h1>Lean workbench.</h1><p class="intro">Write locally, check through the runner, and keep your proof artifacts portable.</p><div class="two-col"><div class="panel"><div class="panel-heading"><h2>Solution.lean</h2><span>PINNED PROOF PROFILE</span></div><textarea class="code-input tall" v-model="form.source"></textarea><div class="button-row"><button @click="act('Check Lean source',()=>startJob('check'))">Run Lean check</button><button class="primary" @click="act('Prepare registration',()=>startJob('register'))">Seal a formal goal ↗</button><button @click="download('agora-source.json',{source:form.source,profileId:config.profileId})">Export</button></div></div><div class="panel"><h2>Lean notebook</h2><p class="muted">Save private immutable revisions under your wallet. Restoring a revision changes the editor; it does not rewrite earlier snapshots.</p><label>REVISION TITLE<input v-model="revisionTitle"></label><div class="button-row"><button @click="saveRevision" :disabled="!!busy">Save source revision</button><button @click="loadNotebook" :disabled="!!busy">Load my revisions</button><button v-if="notebook.length" @click="download('agora-notebook.json',notebook)">Export notebook</button></div><article class="notebook-revision" v-for="r in notebook"><b>{{r.title}}</b><small>{{new Date(r.createdAt).toLocaleString()}}</small><code>{{short(r.sourceHash)}}</code><button @click="restoreRevision(r)">Restore into editor</button></article><hr><h2>Computation journal</h2><p class="muted">A successful Lean check does not resolve a market. Every accepted settlement also requires an EVM-verified certificate.</p><div v-if="!jobs.length" class="subtle-empty">Your check and proof jobs appear here.</div><div v-for="j in jobs" class="job"><div><b>{{j.input.action}} · {{j.status}}</b><small>{{new Date(j.createdAt).toLocaleTimeString()}}</small></div><pre>{{j.diagnostics || (j.status === 'succeeded' ? (j.result?.status === 'checked' ? 'Lean and the pinned checker accepted the proof. No zk certificate was requested.' : 'Certificate generated. Download the verified result below.') : ['queued','running'].includes(j.status) ? 'Waiting for the isolated runner…' : j.status === 'cancelled' ? 'Job cancelled.' : 'Job failed; inspect the result for details.')}}</pre><button v-if="j.result" @click="download('agora-result.json',j.result)">Download artifact</button><button v-if="['queued','running'].includes(j.status)" @click="act('Cancel job',()=>api(`/jobs/${j.id}/cancel`,{method:'POST'}))">Cancel</button></div></div></div></section>

 <section v-else-if="page==='portfolio'"><div class="eyebrow">YOUR RESEARCH CAPITAL</div><h1>My positions.</h1><p class="intro">{{short(account)}} · Balances read directly from the Agora chain.</p><div class="stats-grid"><div><span>AVAILABLE TRUE</span><strong>{{amount(portfolio?.t)}} <small>T</small></strong></div><div><span>GAS BALANCE</span><strong>{{amount(portfolio?.eth)}} <small>test ETH</small></strong></div><div><span>TEST NETWORK ONLY</span><button class="text-button" @click="act('Receive local test funds',()=>api('/faucet',{method:'POST',body:{address:account}}))">Get 1,000 test T ↗</button></div></div><div class="panel"><h2>Statement positions</h2><table><thead><tr><th>Statement</th><th>YES</th><th>NO</th><th>LP shares</th><th>Status</th></tr></thead><tbody><tr v-for="p in portfolio?.positions" @click="openMarket(p)"><td>{{p.metadata.title}}</td><td>{{amount(p.yes)}}</td><td>{{amount(p.no)}}</td><td>{{amount(p.lp[0]?.balance)}}</td><td>{{p.outcome===0?'Open':p.outcome===1?'True':'False'}} ↗</td></tr></tbody></table><p v-if="!portfolio?.positions.length" class="subtle-empty">Trade a statement or provide liquidity to begin.</p></div></section>

 <section v-else-if="page==='shelf'"><div class="eyebrow">QUESTIONS TO RETURN TO</div><h1>Research shelf.</h1><p class="intro">Your saved statements and private research notes.<br>Only your signed-in wallet can read or edit this shelf.</p><div class="two-col"><article class="panel" v-for="item in shelf"><div class="panel-heading"><h2>{{list.find(m=>m.id===item.statementId)?.metadata.title??short(item.statementId)}}</h2><span>{{list.find(m=>m.id===item.statementId)?.outcome===0?'OPEN':'SETTLED'}}</span></div><code>{{short(item.statementId)}}</code><label>PRIVATE NOTES<textarea v-model="item.notes" maxlength="10000" rows="5" placeholder="An approach to try, a useful reference, a question for later…"></textarea></label><div class="button-row"><button @click="saveBookmark(item.statementId,item.notes)" :disabled="!!busy">Save notes</button><button class="primary" @click="openMarket(list.find(m=>m.id===item.statementId))">Open statement ↗</button><button @click="removeBookmark(item.statementId)" :disabled="!!busy">Remove</button></div></article></div><div class="panel subtle-empty" v-if="!shelf.length">Save a statement from its overview to build your reading list.</div></section>

 <section v-else-if="page==='profile'&&profile" class="narrow-page"><div class="eyebrow">A WALLET, A RESEARCHER</div><div class="profile-heading"><div class="large-avatar">{{profile.displayName.slice(0,2).toUpperCase()}}</div><div><h1>{{profile.displayName}}</h1><code class="full-address">{{profile.address}}</code></div></div><p class="intro">{{profile.bio||'This researcher has not added a biography yet.'}}</p><div class="stats-grid"><div><span>CONTRIBUTIONS</span><strong>{{profile.commentCount}} <small>comments & replies</small></strong></div><div><span>IDENTITY</span><strong>Wallet <small>SIWE verified writes</small></strong></div></div><div class="panel" v-if="profileAddress.toLowerCase()===account.toLowerCase()"><h2>Edit your profile</h2><p class="muted">Your display name and biography are offchain. Your wallet address remains visible and identifies every contribution.</p><label>DISPLAY NAME<input v-model="profileDraft.displayName" maxlength="48"></label><label>BIOGRAPHY<textarea v-model="profileDraft.bio" maxlength="1000" rows="5"></textarea></label><button class="primary" :disabled="!!busy||!profileDraft.displayName.trim()" @click="saveProfile">Sign in & save profile</button></div><div class="research-note"><span>REPUTATION / DISCUSSION</span><p>Comment votes help readers find useful contributions. They have no effect on theorem resolution, token payouts, council signatures or beneficiary shares.</p></div><button class="text-button" @click="page='markets'">Explore statements ↗</button></section>

 <section v-else-if="page==='revenue'"><div class="eyebrow">CONSENT, MADE EXPLICIT</div><h1>Protocol revenue.</h1><p class="intro">Every fee belongs to the allocation epoch active at its trade.<br>A smaller share requires that beneficiary’s own consent.</p><div class="two-col"><div class="panel"><div class="panel-heading"><h2>Current allocation</h2><span>EPOCH {{allocation?.epoch}}</span></div><div class="balance-row" v-for="(a,i) in allocation?.recipients"><span>{{short(a)}} <small v-if="a.toLowerCase()===account.toLowerCase()">you</small></span><strong>{{Number(allocation.shares[i])/10000}}%</strong></div><h3 class="spaced">Propose a new allocation</h3><p class="muted">One address and percentage per line. Total must be 100%. Only addresses whose share decreases must approve.</p><textarea class="code-input" v-model="allocationText" rows="5"></textarea><button class="primary" :disabled="!!busy" @click="proposeAllocation">Propose allocation</button></div><div class="panel"><h2>Your fee claims</h2><div class="epoch" v-for="e in allocation?.epochs"><div><b>Epoch {{e.epoch}}</b><code>{{short(e.split)}}</code><p>{{amount(e.balance)}} T held in immutable splitter</p></div><div><strong>{{amount(e.claimable)}} T</strong><button :disabled="busy||BigInt(e.claimable)===0n" @click="act('Claim epoch revenue',()=>send(e.split,'PaymentSplitter','release',[config.token,account]))">Claim T ↗</button></div></div><p class="muted">Payments use the original OpenZeppelin PaymentSplitter. Historical epochs are independent; current share changes do not reassign old funds.</p></div></div><div class="panel"><h2>Allocation proposals</h2><article class="proposal" v-for="p in allocation?.proposals"><div><b>Proposal #{{p.id}}</b><span>Base epoch {{p.baseVersion}} · {{p.executed?'Applied':Number(p.baseVersion)!==allocation.epoch?'Stale':'Awaiting consent'}}</span></div><div class="allocation-lines"><code v-for="(a,i) in p.payees">{{short(a)}} → {{Number(p.shares[i])/10000}}%</code></div><div class="button-row"><button @click="act('Approve share decrease',()=>send(config.allocation,'AllocationController','setApproval',[BigInt(p.id),true]))">Give my consent</button><button @click="act('Revoke consent',()=>send(config.allocation,'AllocationController','setApproval',[BigInt(p.id),false]))">Revoke</button><button class="primary" @click="act('Apply allocation',()=>send(config.allocation,'AllocationController','execute',[BigInt(p.id)]))">Apply</button></div></article><p class="subtle-empty" v-if="!allocation?.proposals.length">No allocation changes proposed.</p></div></section>

 <section v-else-if="page==='governance'"><div class="eyebrow">THE RULES OF THE COMMONS</div><h1>Governance.</h1><p class="intro">A two-member Safe council schedules decisions through an OpenZeppelin timelock.<br>The council cannot resolve a theorem or bypass beneficiary consent.</p><div class="governance-summary"><div><label>SAFE COUNCIL</label><code>{{short(config.safe)}}</code></div><div><label>SIGNATURE THRESHOLD</label><strong>{{gov?.threshold}} of {{gov?.owners.length}}</strong></div><div><label>TIMELOCK</label><strong>5 seconds <small>local test setting</small></strong></div></div><div class="two-col"><div class="panel"><h2>Propose a protocol extension</h2><p class="muted">New verifier and operator versions are immutable. Disabling a profile retires new registrations; existing statements can still resolve under their pinned verifier.</p><details><summary>Available extension example</summary><p>ResolvedAfterOperator returns TRUE when its dependency settles strictly after the ABI-encoded uint64 deadline. Pending dependency stays unresolved.</p><code>{{config.operatorCandidate}}</code><button @click="prepareOperator">Prepare this operator proposal</button></details><label>TITLE<input v-model="newGov.title"></label><label>OPERATION<select v-model="newGov.kind"><option value="profile">Register a new verifier profile</option><option value="disable">Change registration availability</option><option value="operator">Approve a new operator version</option></select></label><label>{{newGov.kind==='operator'?'OPERATOR VERSION ID':'PROFILE ID'}} · BYTES32<input v-model="newGov.profileId" :placeholder="config.profileId"></label><template v-if="newGov.kind!=='disable'"><label>{{newGov.kind==='operator'?'EVALUATOR':'VERIFIER'}} ADDRESS<input v-model="newGov.verifier" :placeholder="config.verifier"></label><label>BUILD MANIFEST HASH · BYTES32<input v-model="newGov.manifestHash" placeholder="0x…"></label></template><label class="checkbox" v-else><input v-model="newGov.enabled" type="checkbox">Enable new registrations</label><button class="primary" @click="createGovernance" :disabled="!!busy">Create proposal</button></div><div><article class="panel" v-for="p in gov?.proposals"><div class="panel-heading"><h2>{{p.title}}</h2><span>{{p.done?'EXECUTED':p.ready?'READY':'COLLECTING SIGNATURES'}}</span></div><p>{{p.signatures.length}} of 2 council signatures · Safe nonce {{p.nonce}}</p><code class="block-code">Target {{p.target}}<br>Operation {{p.operationId}}</code><details><summary>Inspect exact calldata</summary><pre>{{p.data}}</pre></details><div class="button-row"><button @click="signGovernance(p)">Sign</button><button :disabled="p.signatures.length<2" @click="scheduleGovernance(p)">Schedule via Safe</button><button class="primary" @click="executeGovernance(p)">Execute</button></div></article><div v-if="!gov?.proposals.length" class="panel subtle-empty">No protocol changes proposed.<br>Every decision will display its exact target and calldata here.</div></div></div></section>

 <section v-else-if="page==='activity'"><div class="page-title-row"><div><div class="eyebrow">THE CHAIN IS THE RECORD</div><h1>Activity explorer.</h1></div><button @click="loadActivity">Refresh ↻</button></div><p class="intro">Local chain 31371. Blocks, transaction receipts, actors and decoded asset movements.</p><div v-if="!activity" class="subtle-empty">Reading blocks…</div><article class="block-panel" v-for="b in activity?.blocks.filter(b=>b.transactions.length)"><div class="block-heading"><div><b>Block {{b.number}}</b><time>{{time(b.timestamp)}}</time></div><code>{{b.hash}}</code></div><div class="transaction" v-for="t in b.transactions"><div class="tx-heading"><span :class="t.status==='success'?'good':'bad'">{{t.status==='success'?'✓':'×'}} {{t.status}}</span><code>{{t.hash}}</code></div><div class="tx-meta"><span>Actor {{t.actor}}</span><span>To {{t.to??'Contract creation'}}</span><span>Gas {{t.gasUsed}}</span></div><div class="event-tags"><span v-for="e in t.events">{{e.event}}</span></div><details><summary>{{t.events.length}} decoded events · {{t.changes.length}} asset movements</summary><h3>Net balance changes</h3><div class="movement" v-for="d in t.balanceDeltas"><code>{{short(d.address)}}</code><span>{{d.asset==='ETH'?'ETH (includes gas)':short(d.asset)}}{{d.positionId?` / ${short(d.positionId)}`:''}}</span><b>{{BigInt(d.delta)>0n?'+':''}}{{amount(d.delta)}}</b></div><h3>Asset transfers</h3><div class="movement" v-for="c in t.changes"><code>{{short(c.asset)}}{{c.positionId?` / position ${short(c.positionId)}`:''}}</code><span>{{short(c.from)}} → {{short(c.to)}}</span><b>{{amount(c.amount)}}</b></div><pre>{{stringify(t.events)}}</pre></details></div></article></section>
 </main><div v-else class="loading">Connecting to the Agora research chain…</div><footer>AGORA / OPEN MATHEMATICS <span>Gnosis CTF + FPMM · Immutable revenue epochs · Safe governance</span><b>Test assets only</b></footer>
 </div>
</div>
</template>
